(()=>{const box=document.querySelector('.quiz'),area=box.querySelector('[data-quiz-area]'),images=["data:image/png;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];box.querySelector('img').src=images[0];box.querySelector('h2').innerHTML='ПОЛУЧИ ПРОБНОЕ ЗАНЯТИЕ<br><span>БЕСПЛАТНО</span>';const qs=[['Я ПОДБИРАЮ СТУДИЮ',['Для себя','Для ребёнка']],['КАКОЕ НАПРАВЛЕНИЕ ДЛЯ ВАС НАИБОЛЕЕ ИНТЕРЕСНО',['Вокал','Гитара','Фортепиано','Пока не определился']],['ЕСТЬ ЛИ У ВАС ОПЫТ?',['Нет, совсем никакого','Пробовал посещать занятия раньше','Уже занимаюсь, но ищу новую студию','Профессионал']],['КАКОЙ ИЗ ЭТИХ ПУНКТОВ О ВАС?',['Хочу попробовать новое хобби','Занимаюсь давно и хочу продолжать дальше для себя','Мечтаю стать звездой','Хочу повысить уверенность в себе']],['СКОЛЬКО ВРЕМЕНИ ВЫ ГОТОВЫ ПОСВЯТИТЬ ЗАНЯТИЯМ?',['1 час в неделю','2 часа в неделю','3 часа в неделю']]];let step=0,advanceTimer=null;const selected=[];function nextStep(){clearTimeout(advanceTimer);advanceTimer=null;if(step<5&&selected[step]!==undefined){step++;render()}}function render(){clearTimeout(advanceTimer);advanceTimer=null;box.dataset.quizStep=String(step);area.innerHTML='<div class="quiz-progress"><i style="width:'+((step+1)/6*100)+'%"></i></div>'+(step<5?'<div class="quiz-options"><h3>'+qs[step][0]+'</h3>'+(step===4?'<p class="quiz-subtitle">И ПОСЛЕДНИЙ ВОПРОС</p>':'')+'<div class="quiz-choices '+(step===0?'image-choices':step===4?'quiz-hours':'')+'">'+qs[step][1].map((x,i)=>'<label>'+(step===0?'<img src="'+images[i+1]+'" alt="">':'')+(step===0?'<span>':'')+'<input type="radio" name="bm-choice" value="'+i+'" '+(selected[step]===i?'checked':'')+'>'+(step===0?x:'<span class="quiz-answer-text">'+x+'</span>')+(step===0?'</span>':'')+'</label>').join('')+'</div></div>':'<div class="quiz-options quiz-final"><h3>ОСТАВЬТЕ СВОИ КОНТАКТЫ, ЧТОБЫ МЫ МОГЛИ ПОДОБРАТЬ ВАМ УДОБНОЕ ВРЕМЯ ДЛЯ БЕСПЛАТНОГО ЗАНЯТИЯ</h3><p class="quiz-final-description">Обещаем, что не будем звонить по ночам и предлагать курсы и вебинары</p><form class="quiz-contact"><label class="quiz-field">Ваше имя<input name="Name" autocomplete="name" required></label><label class="quiz-field">Телефон<input name="Phone" type="tel" autocomplete="tel" required></label><label class="quiz-consent"><input type="checkbox" required><span>Я даю своё согласие на обработку персональных данных в соответствии с <a href="./privacy.html" target="_blank" rel="noopener">Положением об обработке и защите персональных данных</a></span></label><label class="quiz-consent"><input type="checkbox"><span>Я даю <a href="./email.html" target="_blank" rel="noopener">Согласие на получение рекламной и информационной рассылки</a></span></label></form></div>')+'<div class="quiz-bottom"><div class="quiz-footer-text"><small><span>Шаг: </span><span>'+ (step+1)+'/6</span></small><b>ПРОСТО ПРОЙДИ ТЕСТ ДО КОНЦА</b></div><div class="quiz-footer-buttons">'+(step>0?'<button class="quiz-back" aria-label="Предыдущий вопрос"><svg role="presentation" viewBox="0 0 18 18" fill="none" width="18" height="18"><path d="M14.25 9H3.75M9 3.75L3.75 9L9 14.25" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"></path></svg></button>':'')+(step<5?'<button class="cta quiz-next" '+(selected[step]===undefined?'disabled':'')+'>ДАЛЕЕ →</button>':'<button class="cta quiz-submit" type="button" disabled>ОТПРАВИТЬ</button>')+'</div></div>';area.scrollTop=0;area.querySelector('form')?.addEventListener('submit',e=>e.preventDefault());area.querySelectorAll('input[type=radio]').forEach(r=>r.onchange=()=>{selected[step]=Number(r.value);area.querySelector('.quiz-next').disabled=false;clearTimeout(advanceTimer);const answeredStep=step;advanceTimer=setTimeout(()=>{if(step===answeredStep)nextStep()},300)});const next=area.querySelector('.quiz-next');if(next)next.onclick=nextStep;const back=area.querySelector('.quiz-back');if(back)back.onclick=()=>{step--;render()}}render()})();